/* Worker offline BVH queries and eight-influence skinning. Derived from cathexis_contacts.c. */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
typedef struct{double x,y,z;} V;typedef struct{double a[16];} M;typedef struct{unsigned a,b,c;} T;typedef struct{V a,b,c;} Tri;typedef struct{V lo,hi;} Box;typedef struct{Box b;int begin,end,l,r;} Node;typedef struct{Node*n;unsigned*order;Tri*tris;Box*boxes;int size,nt;} BVH;
V add(V a,V b){return(V){a.x+b.x,a.y+b.y,a.z+b.z};}V sub(V a,V b){return(V){a.x-b.x,a.y-b.y,a.z-b.z};}V scale(V a,double b){return(V){a.x*b,a.y*b,a.z*b};}V cross(V a,V b){return(V){a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}double dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
V xform(M m,V v){double*a=m.a;return(V){a[0]*v.x+a[1]*v.y+a[2]*v.z+a[3],a[4]*v.x+a[5]*v.y+a[6]*v.z+a[7],a[8]*v.x+a[9]*v.y+a[10]*v.z+a[11]};}M mul(M a,M b){M c={0};for(int i=0;i<4;i++)for(int j=0;j<4;j++)for(int k=0;k<4;k++)c.a[4*i+j]+=a.a[4*i+k]*b.a[4*k+j];return c;}
Box empty(){return(Box){{1e20,1e20,1e20},{-1e20,-1e20,-1e20}};}void point(Box*b,V p){b->lo=(V){fmin(b->lo.x,p.x),fmin(b->lo.y,p.y),fmin(b->lo.z,p.z)};b->hi=(V){fmax(b->hi.x,p.x),fmax(b->hi.y,p.y),fmax(b->hi.z,p.z)};}void boxadd(Box*b,Box c){point(b,c.lo);point(b,c.hi);}Box bounds(Tri t){Box b=empty();point(&b,t.a);point(&b,t.b);point(&b,t.c);return b;}int overlap(Box a,Box b){return a.lo.x<=b.hi.x&&a.hi.x>=b.lo.x&&a.lo.y<=b.hi.y&&a.hi.y>=b.lo.y&&a.lo.z<=b.hi.z&&a.hi.z>=b.lo.z;}
int edge(V p,V q,Tri b){V e1=sub(b.b,b.a),e2=sub(b.c,b.a),dir=sub(q,p),h=cross(dir,e2);double det=dot(e1,h);if(fabs(det)<1e-12)return 0;V s=sub(p,b.a);double u=dot(s,h)/det;V z=cross(s,e1);double v=dot(dir,z)/det,t=dot(e2,z)/det;return u>1e-5&&v>1e-5&&u+v<1-1e-5&&t>1e-5&&t<1-1e-5;}
int hit(Tri a,Tri b){return edge(a.a,a.b,b)||edge(a.b,a.c,b)||edge(a.c,a.a,b)||edge(b.a,b.b,a)||edge(b.b,b.c,a)||edge(b.c,b.a,a);}
static Box*sortboxes;static int dim;double coord(V a,int d){return d==0?a.x:d==1?a.y:a.z;}int compare(const void*a,const void*b){Box x=sortboxes[*(unsigned*)a],y=sortboxes[*(unsigned*)b];double d=coord(add(x.lo,x.hi),dim)-coord(add(y.lo,y.hi),dim);return(d>0)-(d<0);}
int build(BVH*b,int a,int z){int id=b->size++;Node*n=&b->n[id];n->begin=a;n->end=z;n->l=n->r=-1;n->b=empty();Box c=empty();for(int i=a;i<z;i++){Box t=b->boxes[b->order[i]];boxadd(&n->b,t);point(&c,scale(add(t.lo,t.hi),.5));}if(z-a>8){V size=sub(c.hi,c.lo);dim=size.y>size.x?1:0;if(size.z>coord(size,dim))dim=2;sortboxes=b->boxes;qsort(b->order+a,z-a,sizeof(unsigned),compare);int mid=(a+z)/2;n->l=build(b,a,mid);n->r=build(b,mid,z);}return id;}
void update(BVH*b,V*v,T*t,int nt){if(b->n&&b->nt!=nt){free(b->n);free(b->order);free(b->tris);free(b->boxes);memset(b,0,sizeof(*b));}if(!b->n){b->nt=nt;b->n=calloc(nt*2,sizeof(Node));b->order=calloc(nt,sizeof(unsigned));b->tris=calloc(nt,sizeof(Tri));b->boxes=calloc(nt,sizeof(Box));for(int i=0;i<nt;i++)b->order[i]=i;}for(int i=0;i<nt;i++){b->tris[i]=(Tri){v[t[i].a],v[t[i].b],v[t[i].c]};b->boxes[i]=bounds(b->tris[i]);}if(!b->size)build(b,0,nt);else for(int i=b->size-1;i>=0;i--){Node*n=&b->n[i];n->b=empty();if(n->l<0){for(int j=n->begin;j<n->end;j++)boxadd(&n->b,b->boxes[b->order[j]]);}else{boxadd(&n->b,b->n[n->l].b);boxadd(&n->b,b->n[n->r].b);}}}
int query(BVH*b,Tri a,Box box,int id){Node*n=&b->n[id];if(!overlap(n->b,box))return-1;if(n->l<0){for(int i=n->begin;i<n->end;i++){int j=b->order[i];if(overlap(b->boxes[j],box)&&hit(a,b->tris[j]))return j;}return-1;}int j=query(b,a,box,n->l);return j>=0?j:query(b,a,box,n->r);}

static BVH b={0},leg_b={0}; int count_contacts(BVH*tree,V*v,T*cloth,int nc,T*legs,int nl){update(tree,v,cloth,nc);int n=0;for(int i=0;i<nl;i++){T t=legs[i];Tri a={v[t.a],v[t.b],v[t.c]};if(query(tree,a,bounds(a),0)>=0)n++;}return n;}
int contacts(V*v,T*cloth,int nc,T*legs,int nl){static BVH cache[32]={0}; int slot=0; while(slot<31 && cache[slot].nt && cache[slot].nt!=nc)slot++; return count_contacts(&cache[slot],v,cloth,nc,legs,nl);}
int leg_contacts(V*v,T*left,int nl,T*right,int nr){return count_contacts(&leg_b,v,left,nl,right,nr);}
void skin_vertices(double*v,unsigned*j,double*w,int nv,double*m,double*out){for(int i=0;i<nv;i++){double x=v[3*i],y=v[3*i+1],z=v[3*i+2];double*p=out+3*i;p[0]=p[1]=p[2]=0;for(int k=0;k<8;k++){double wt=w[8*i+k];if(wt<1e-10)continue;double*a=m+16*j[8*i+k];for(int d=0;d<3;d++)p[d]+=wt*(a[4*d]*x+a[4*d+1]*y+a[4*d+2]*z+a[4*d+3]);}}}
int any_contacts(V*v,T*a,int na,T*c,int nc){static BVH trees[32]={0};int s=0;while(s<31&&trees[s].nt&&trees[s].nt!=na)s++;BVH*t=&trees[s];update(t,v,a,na);for(int i=0;i<nc;i++){T k=c[i];Tri tri={v[k.a],v[k.b],v[k.c]};if(query(t,tri,bounds(tri),0)>=0)return 1;}return 0;}
